import { Ionicons } from '@expo/vector-icons';
import { useLocalSearchParams, useRouter } from 'expo-router';
import React, { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, StyleSheet, View } from 'react-native';

import { Text } from '@/components/ui/sl-text';
import { FloatingDisplayUnitRegistration, SLCanonicalIcon, SLTrophy } from '@/components/ui';
import { SLColors, SLRadius, SLSpacing } from '@/constants/theme';
import { ledgerHrefFor } from './routing';
import { fetchArchiveDetail, type ArchiveItem, type ArchiveItemType } from '@/lib/ledger-archive';
import { useAuth } from '@/context/AuthContext';
import { formatWeightFromKg, normalizeDisplayWeightUnit, type DisplayWeightUnit } from '@/lib/display-units';
import { useSurfaceWeightUnit } from '@/lib/surface-weight-unit';
import { useAthleteLedgerSubject } from './athlete-ledger-subject';
import SetVideoPlayerModal from '@/components/SetVideoPlayerModal';

const first = (value: string | string[] | undefined) => Array.isArray(value) ? value[0] : value;
const ArchiveDetailUnitContext = React.createContext<DisplayWeightUnit>('lb');

type ArchiveDetailItem = ArchiveItem & {
  sets?: ArchiveItem[];
  athlete_reflection?: Record<string, unknown> | null;
  athlete_visible_coach_feedback?: string | null;
  history_url?: string;
  match_scope?: string;
};

const TYPE_META: Record<ArchiveItemType, { label: string; icon: keyof typeof Ionicons.glyphMap; tone: string }> = {
  session: { label: 'Training session', icon: 'barbell-outline', tone: '#A98CFF' },
  set: { label: 'Performed set', icon: 'pulse-outline', tone: '#A98CFF' },
  video: { label: 'Preserved film', icon: 'videocam-outline', tone: '#5ED7CA' },
  meet: { label: 'Competition record', icon: 'trophy-outline', tone: '#D4AD62' },
  movement: { label: 'Movement history', icon: 'git-branch-outline', tone: '#7FA7D8' },
  historical_performance: { label: 'Imported history', icon: 'time-outline', tone: '#7FA7D8' },
};

function readable(key: string): string {
  const labels: Record<string, string> = {
    duration_seconds: 'Duration',
    movement_count: 'Movements',
    set_count: 'Sets',
    total_volume_kg: 'Total volume',
    video_count: 'Videos',
    block_name: 'Block',
    program_name: 'Program',
  };
  return labels[key] || key.replace(/_(kg|seconds)$/, '').replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function visibleFields(value?: Record<string, unknown> | null) {
  return Object.entries(value || {}).filter(([key, entry]) => (
    entry !== null && entry !== undefined && typeof entry !== 'object'
    && key !== 'id' && !key.endsWith('_id')
  ));
}

function displayValue(key: string, value: unknown, unit: DisplayWeightUnit): string {
  if (typeof value === 'boolean') return value ? 'Yes' : 'No';
  if (typeof value === 'number') {
    const formatted = Number.isInteger(value) ? String(value) : value.toFixed(2).replace(/0+$/, '').replace(/\.$/, '');
    if (key.endsWith('_kg')) return formatWeightFromKg(value, unit, 2) || '—';
    if (key.endsWith('_seconds')) {
      const minutes = Math.floor(value / 60);
      const seconds = Math.floor(value % 60);
      return `${minutes}:${String(seconds).padStart(2, '0')}`;
    }
    return formatted;
  }
  return String(value);
}

function dateLabel(value?: string): string {
  if (!value) return 'Date unavailable';
  const parsed = new Date(`${value}T12:00:00`);
  return Number.isNaN(parsed.getTime()) ? value : parsed.toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' });
}

function recordStatusLabel(status?: string | null): string {
  const labels: Record<string, string> = {
    assigned: 'Planned',
    canceled: 'Canceled',
    completed: 'Completed',
    in_progress: 'In progress',
    missed: 'Missed',
    reviewed: 'Reviewed',
    submitted: 'Submitted',
  };
  return labels[String(status || '').toLowerCase()] || 'Recorded';
}

export function ArchiveDetailExperience() {
  const router = useRouter();
  const ledgerSubject = useAthleteLedgerSubject();
  const { user } = useAuth();
  const preferredDisplayUnit = normalizeDisplayWeightUnit(user?.preferred_units);
  const params = useLocalSearchParams<{ itemType?: string; sourceId?: string; collection?: string; q?: string; athlete_id?: string; date_from?: string; date_to?: string; displayUnit?: string; returnTo?: string }>();
  const itemType = first(params.itemType) as ArchiveItemType;
  const sourceId = Number(first(params.sourceId));
  const athleteId = ledgerSubject.athleteId ?? (Number(first(params.athlete_id)) || undefined);
  const [item, setItem] = useState<ArchiveDetailItem | null>(null);
  const [state, setState] = useState<'loading' | 'ready' | 'unavailable' | 'unauthorized' | 'error'>('loading');
  const [reloadToken, setReloadToken] = useState(0);
  const [videoOpen, setVideoOpen] = useState(false);
  const { unit: displayUnit, setUnit: setDisplayUnit } = useSurfaceWeightUnit(preferredDisplayUnit, first(params.displayUnit));

  useEffect(() => {
    let active = true;
    setState('loading');
    setItem(null);
    setVideoOpen(false);
    if (!itemType || !Number.isInteger(sourceId)) { setState('unavailable'); return; }
    fetchArchiveDetail(itemType, sourceId, athleteId)
      .then((payload) => { if (active) { setItem(payload.item as ArchiveDetailItem); setState('ready'); } })
      .catch((error: Error & { status?: number }) => { if (active) setState(
        error.status === 401 || error.status === 403
          ? 'unauthorized'
          : error.status === 404 || error.status === 410
            ? 'unavailable'
            : 'error',
      ); });
    return () => { active = false; };
  }, [athleteId, itemType, reloadToken, sourceId, user?.id]);

  const back = () => router.replace({ pathname: ledgerHrefFor('archive') as never, params: { collection: first(params.collection), q: first(params.q), athlete_id: athleteId ? String(athleteId) : undefined, date_from: first(params.date_from), date_to: first(params.date_to), displayUnit, returnTo: first(params.returnTo) === 'today' ? 'today' : undefined, ...ledgerSubject.routeParams } } as never);
  const meta = TYPE_META[itemType] || TYPE_META.session;

  return <ArchiveDetailUnitContext.Provider value={displayUnit}><View style={styles.page} testID="ledger-archive-detail">
    <FloatingDisplayUnitRegistration unit={displayUnit} onChange={setDisplayUnit} testID="ledger-archive-detail-unit-toggle" />
    <Pressable accessibilityLabel="Back to Archive results" onPress={back} style={styles.back}><Ionicons name="chevron-back" size={20} color={SLColors.iconPrimary} /><Text typographyRole="shortButtonLabel" style={styles.backText}>Archive</Text></Pressable>
    {state === 'loading' ? <DetailState loading icon="layers-outline" title="Opening record" body="Loading your saved training history…" /> : null}
    {state === 'unauthorized' ? <DetailState icon="lock-closed-outline" title="Archive unavailable" body="You do not have access to this record right now." /> : null}
    {state === 'unavailable' ? <DetailState icon="unlink-outline" title="Record unavailable" body="This record is no longer available." /> : null}
    {state === 'error' ? <DetailState icon="alert-circle-outline" title="Could not open this record" body="Please try again." action="Try again" onAction={() => { setState('loading'); setReloadToken((value) => value + 1); }} /> : null}
    {state === 'ready' && item ? <View style={styles.detail}>
      <View style={styles.masthead}>
        <View style={[styles.typeSeal, { borderColor: `${meta.tone}70` }]}><SLCanonicalIcon name={meta.icon} size={26} color={meta.tone} trophyTier="bronze" /></View>
        <Text typographyRole="shortTechnicalLabel" style={[styles.kicker, { color: meta.tone }]}>{item.provenance_label || meta.label}</Text>
        <Text typographyRole="pageTitle" style={styles.title}>{item.title || String(item.movement?.name || meta.label)}</Text>
        {item.subtitle ? <Text typographyRole="body" style={styles.body}>{item.subtitle}</Text> : null}
        <View style={styles.metaRow}><MetaPill icon="calendar-outline" label={dateLabel(item.occurred_on)} /><MetaPill icon="shield-checkmark-outline" label={recordStatusLabel(item.status)} /></View>
      </View>

      {item.archive_item_type === 'video' ? <Pressable accessibilityRole="button" accessibilityLabel="Play video" onPress={() => setVideoOpen(true)} style={styles.playVideo}>
        <Ionicons name="play-circle" size={30} color="#70D7D0" />
        <Text typographyRole="bodyStrong" style={styles.playVideoText}>Play video</Text>
        <Ionicons name="arrow-forward" size={18} color="#70D7D0" />
      </Pressable> : null}

      {item.invalidation_state && item.invalidation_state !== 'valid' ? <View style={styles.integrity}><Ionicons name="information-circle-outline" size={21} color={SLColors.accentMuted} /><View style={styles.integrityCopy}><Text typographyRole="bodyStrong" style={styles.integrityTitle}>No longer current</Text><Text typographyRole="caption" style={styles.integrityBody}>This entry is kept for history.</Text></View></View> : null}

      <DetailSection icon="speedometer-outline" title="Performance" value={item.performance} />
      {item.reported_bodyweight ? <DetailSection icon="scale-outline" title="Reported bodyweight" value={{ reported_bodyweight_kg: item.reported_bodyweight.reported_bodyweight_kg, training_date: item.reported_bodyweight.training_date, source: 'Pre-Session readiness' }} /> : null}
      <DetailSection icon="git-branch-outline" title="Movement" value={item.movement} />
      <DetailSection icon="albums-outline" title="Program" value={item.program_context} />
      <MeetSection value={item.meet_context} />
      <DetailSection icon="videocam-outline" title="Film" value={item.media} />
      {item.sets?.length ? <SetEvidence items={item.sets} /> : null}
      <DetailSection icon="create-outline" title="Athlete reflection" value={item.athlete_reflection} />
      {item.athlete_visible_coach_feedback ? <View style={styles.feedback}><View style={styles.feedbackIcon}><Ionicons name="chatbubble-ellipses-outline" size={21} color="#5ED7CA" /></View><View style={styles.feedbackCopy}><Text typographyRole="shortTechnicalLabel" style={styles.feedbackLabel}>ATHLETE-VISIBLE COACH FEEDBACK</Text><Text typographyRole="body" style={styles.feedbackBody}>{item.athlete_visible_coach_feedback}</Text></View></View> : null}
    </View> : null}
    <SetVideoPlayerModal visible={videoOpen && state === 'ready' && item?.archive_item_type === 'video'} videoId={item?.archive_item_type === 'video' ? item.source_id : null} allowExport={athleteId == null || athleteId === user?.athlete_id || athleteId === user?.self_athlete_id ? undefined : false} onClose={() => setVideoOpen(false)} />
  </View></ArchiveDetailUnitContext.Provider>;
}

function MetaPill({ icon, label }: { icon: keyof typeof Ionicons.glyphMap; label: string }) {
  return <View style={styles.metaPill}><Ionicons name={icon} size={14} color={SLColors.iconMuted} /><Text typographyRole="caption" style={styles.metaText}>{label}</Text></View>;
}

function DetailState({ icon, title, body, loading = false, action, onAction }: { icon: keyof typeof Ionicons.glyphMap; title: string; body: string; loading?: boolean; action?: string; onAction?: () => void }) {
  return <View style={styles.state}>{loading ? <ActivityIndicator color={SLColors.accent} /> : <View style={styles.stateIcon}><Ionicons name={icon} size={31} color={SLColors.accentMuted} /></View>}<Text typographyRole="emptyStateTitle" style={styles.stateTitle}>{title}</Text><Text typographyRole="emptyStateBody" style={styles.stateBody}>{body}</Text>{action && onAction ? <Pressable accessibilityRole="button" onPress={onAction} style={styles.stateAction}><Text typographyRole="shortButtonLabel" style={styles.stateActionText}>{action}</Text></Pressable> : null}</View>;
}

function DetailSection({ icon, title, value }: { icon: keyof typeof Ionicons.glyphMap; title: string; value?: Record<string, unknown> | null }) {
  const unit = React.useContext(ArchiveDetailUnitContext);
  const entries = visibleFields(value);
  if (!entries.length) return null;
  return <View style={styles.block}><View style={styles.blockHeading}><View style={styles.blockIcon}><Ionicons name={icon} size={18} color={SLColors.accentMuted} /></View><Text typographyRole="sectionTitle" style={styles.blockTitle}>{title}</Text></View><View style={styles.fields}>{entries.map(([key, entry]) => <View key={key} style={styles.field}><Text typographyRole="caption" style={styles.fieldName}>{readable(key)}</Text><Text typographyRole="bodyStrong" style={styles.fieldValue}>{displayValue(key, entry, unit)}</Text></View>)}</View></View>;
}

function MeetSection({ value }: { value?: Record<string, unknown> | null }) {
  const unit = React.useContext(ArchiveDetailUnitContext);
  if (!value) return null;
  const basic = Object.fromEntries(Object.entries(value).filter(([key, entry]) => !['attempts', 'result_summary'].includes(key) && entry !== null && entry !== undefined));
  const summary = value.result_summary && typeof value.result_summary === 'object' ? value.result_summary as Record<string, unknown> : null;
  const attempts = Array.isArray(value.attempts) ? value.attempts as Record<string, unknown>[] : [];
  return <View style={styles.block}><View style={styles.blockHeading}><View style={[styles.blockIcon, styles.meetBlockIcon]}><SLTrophy size={18} tier="bronze" /></View><Text typographyRole="sectionTitle" style={styles.blockTitle}>Competition evidence</Text></View><DetailFields value={basic} />{summary ? <View style={styles.summaryBand}><Text typographyRole="shortTechnicalLabel" style={styles.summaryLabel}>RESULT SUMMARY</Text><DetailFields value={summary} compact /></View> : null}{attempts.length ? <View style={styles.attempts}><Text typographyRole="shortTechnicalLabel" style={styles.summaryLabel}>ATTEMPTS</Text>{attempts.map((attempt, index) => <View key={String(attempt.id || index)} style={styles.attempt}><Text typographyRole="bodyStrong" style={styles.attemptLift}>{String(attempt.lift || 'Attempt')} {String(attempt.attempt_number || index + 1)}</Text><Text typographyRole="bodyStrong" style={styles.attemptWeight}>{displayValue('weight_kg', attempt.weight_kg, unit)}</Text><Text typographyRole="caption" style={[styles.attemptResult, attempt.result === 'good' && styles.attemptGood]}>{String(attempt.result || 'recorded')}</Text></View>)}</View> : null}</View>;
}

function DetailFields({ value, compact = false }: { value: Record<string, unknown>; compact?: boolean }) {
  const unit = React.useContext(ArchiveDetailUnitContext);
  return <View style={[styles.fields, compact && styles.fieldsCompact]}>{visibleFields(value).filter(([, entry]) => entry !== false).map(([key, entry]) => <View key={key} style={styles.field}><Text typographyRole="caption" style={styles.fieldName}>{readable(key)}</Text><Text typographyRole="bodyStrong" style={styles.fieldValue}>{displayValue(key, entry, unit)}</Text></View>)}</View>;
}

function SetEvidence({ items }: { items: ArchiveItem[] }) {
  const unit = React.useContext(ArchiveDetailUnitContext);
  return <View style={styles.block}><View style={styles.blockHeading}><View style={styles.blockIcon}><Ionicons name="pulse-outline" size={18} color={SLColors.accentMuted} /></View><Text typographyRole="sectionTitle" style={styles.blockTitle}>Performed sets</Text><Text typographyRole="caption" style={styles.setCount}>{items.length}</Text></View><View style={styles.sets}>{items.map((item) => <View key={item.source_id} style={styles.setRow}><Text typographyRole="numeric" style={styles.setIndex}>{String(item.performance?.set_index || '—')}</Text><View style={styles.setCopy}><Text typographyRole="bodyStrong" style={styles.setTitle}>{item.title}</Text><Text typographyRole="caption" style={styles.setDetail}>{setPerformance(item, unit)}</Text></View>{item.media?.video_count ? <Ionicons name="videocam-outline" size={17} color="#5ED7CA" /> : null}</View>)}</View></View>;
}

function setPerformance(item: ArchiveItem, unit: DisplayWeightUnit): string {
  const weight = item.performance?.weight_kg;
  const reps = item.performance?.reps;
  const rpe = item.performance?.rpe;
  const rir = item.performance?.rir;
  return [typeof weight === 'number' ? `${displayValue('weight_kg', weight, unit)}` : null, typeof reps === 'number' ? `${reps} reps` : null, typeof rpe === 'number' ? `RPE ${rpe}` : typeof rir === 'number' ? `${rir} RIR` : null].filter(Boolean).join(' · ') || 'Performed evidence';
}

