  const uploadVideoForSetLog = useCallback(async (setLog: SetLog) => {
    if (!setLog?.id) return;
    const currentUpload = videoUploadBySetLogId[setLog.id];
    if (currentUpload?.uploading || currentUpload?.queued) {
