    const videoId = setLog.video_id || setLog.video?.id;
    if (!setLog?.id || !videoId) return;

    const deleteVideo = async () => {
      try {
        rememberScroll();
        setVideoUploadBySetLogId((prev) => ({
          ...prev,
          [setLog.id]: { uploading: false, deleting: true, error: null } as any,
        }));
