            ...group,
            items: group.items.map((item) => (
              Number(item.id) === Number(itemId)
                ? { ...item, set_logs: [...(item.set_logs || []), mockSet] }
                : item
            )),
          })),
        },
      } : current);
      setAccessoryWheel(null);
      setAccInputs((current) => ({
        ...current,
        [itemId]: {
          weight: formatWheelNumber(weightInUnit),
          reps: '',
          rir: '',
        },
      }));
      setError(null);
      return;
    }
    const clientSubmissionId = await submissionForAttempt(attemptKey, canonicalPayload);
    const timing = createPerformedSetTiming(Number(workoutId), clientSubmissionId, prescribedRestSecondsForItem(itemId));

    const json = await submitCanonicalSet({
      itemId,
      attemptKey,
      clientSubmissionId,
      fallbackError: 'Error logging accessory set',
      request: () => logAccessorySet(
        Number(workoutId),
        itemId,
        {
          ...canonicalPayload,
          client_submission_id: clientSubmissionId,
          timing,
        }
      ),
    });
    if (!json) return;
    rememberAcceptedLoad(itemId, accessorySetIndex, weightKg);

    try {
      markAutoAdvanceAfterAcceptedLog(itemId, json);
      rememberScroll();
      await fetchWorkout({ silent: true, reason: 'post_set' });
      const videoError = await attachSelectedVideoToLoggedSet(json?.set?.id, selectedVideo || null);
      if (selectedVideo && !videoError) await fetchWorkout({ silent: true, reason: 'post_set' });
      if (videoError) setError(videoError);

