            onPress: async () => {
              try {
                await saveVideoMlConsentChoice(false);
              } catch {
                setVideoMlTrainingConsent(false);
              }
              resolve(true);
            },
          },
          {
            text: 'Allow',
            onPress: async () => {
              try {
                await saveVideoMlConsentChoice(true);
              } catch {
                setVideoMlTrainingConsent(true);
              }
              resolve(true);
            },
          },
        ],
      );
    });
