  size: SL_TAB_ROW_CONTROL.shellHeight,
  itemSize: SL_TAB_ROW_CONTROL.itemSize,
  rightInset: SLLayout.screenGutter,
  gap: SLSpacing.sm,
  tabBarBottomInset: SLSpacing.xs,
