}) {
  const foreground = selected ? SL_TAB_ROW_CONTROL.selectedColor : SLColors.textStrong;
  return (
    <SLTabRowControlShell style={[styles.utilityShell, wide && styles.utilityShellWide]}>
      <SLMotionPressable
