        style={[styles.utilityAction, wide && styles.utilityActionWide]}
        testID={testID}
      >
        {selected ? (
          <LinearGradient
            colors={SL_TAB_ROW_SELECTED_LENS}
            end={{ x: 1, y: 1 }}
            pointerEvents="none"
            start={{ x: 0, y: 0 }}
            style={styles.utilitySelectedLens}
          />
        ) : null}
        {icon ? (
          <SLCanonicalIcon
            color={foreground}
            name={icon}
            size={SL_TAB_ROW_CONTROL.iconSize}
            trophyTier="bronze"
