import { useFocusedSession } from '@/lib/session-logger-focus';
// app/(tabs)/_layout.tsx
import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  AppState,
  View,
  StyleSheet,
} from 'react-native';
