    !user.is_coach &&
    (accountState === 'LINK_COACH_REQUIRED' ||
      user.link_coach_required === true ||
      !user.has_linked_athlete ||
      !user.athlete_id);
  const isIndividual = activeMobileMode === 'individual';
  const accessBlocked =
    !!user &&
    (
