export function AthleteCalendarStoryboardV2({
  anchorMonth,
  canManagePersonalEvents = true,
  canRescheduleSessions = false,
  data,
  dayDetail,
  dayDetailError,
  dayDetailLoading = false,
  loadingMore = false,
  loadingPrevious = false,
  navigationRevision = 0,
  onAction,
  onLoadMore,
  onLoadPrevious,
  onMonthChange,
  onMoveSession,
  onRefresh,
  onRetryDayDetail,
  onRetryLoadMore,
  onSelectedDateChange,
  onToday,
  paginationError,
  refreshing = false,
  rescheduleBusy = false,
  reduceMotion = false,
