                  <Ionicons color={SLColors.iconMuted} name="chevron-forward" size={17} />
                </Pressable>
              )) : <Text style={styles.emptySearch}>No matching Calendar evidence.</Text>}
            </View>
          ) : null}
        </View>
      ) : null}

      <FlatList
        data={months}
        getItemLayout={(_, index) => monthLayouts[index] || { index, length: CALENDAR_MONTH_HEIGHT, offset: CALENDAR_MONTH_HEIGHT * index }}
        initialNumToRender={CALENDAR_INITIAL_MONTHS}
        initialScrollIndex={anchorIndex}
        keyExtractor={monthKey}
        maintainVisibleContentPosition={{ minIndexForVisible: 0, autoscrollToTopThreshold: 24 }}
        maxToRenderPerBatch={CALENDAR_RENDER_BATCH}
        onMomentumScrollBegin={beginTimelineGesture}
        onMomentumScrollEnd={endTimelineGesture}
        onScroll={updateTimelineBoundaries}
        onScrollBeginDrag={beginTimelineGesture}
        onScrollEndDrag={endTimelineGesture}
        onViewableItemsChanged={onViewableItemsChanged}
        refreshControl={onRefresh ? <RefreshControl enabled={!dragState} refreshing={refreshing} onRefresh={onRefresh} tintColor={SLColors.accentViolet} /> : undefined}
        ref={listRef}
        renderItem={renderMonth}
        scrollEnabled={!dragState}
        scrollEventThrottle={32}
        showsVerticalScrollIndicator={false}
        style={styles.monthList}
        viewabilityConfig={viewabilityConfig}
        windowSize={CALENDAR_WINDOW_SIZE}
        ListHeaderComponent={loadingPrevious ? <ActivityIndicator color={SLColors.accentViolet} style={styles.pageSpinner} /> : null}
        ListFooterComponent={(
          <View style={styles.listFooter}>
            {loadingMore ? <ActivityIndicator color={SLColors.accentViolet} /> : null}
            {paginationError ? (
              <Pressable onPress={onRetryLoadMore} style={styles.retryRow}>
                <Text style={styles.retryText}>More dates could not load. Tap to retry.</Text>
              </Pressable>
            ) : null}
            <View style={{ height: 148 + insets.bottom }} />
          </View>
        )}
      />

      <View pointerEvents="box-none" style={[styles.floatingControls, { bottom: 70 + insets.bottom }]}>
        <Pressable accessibilityRole="button" onPress={goToday} style={styles.todayButton}>
          <Text style={styles.todayText}>Today</Text>
        </Pressable>
      </View>

      {lensVisible ? (
        <DayLens
          canRescheduleSessions={canRescheduleSessions}
          detail={resolvedDetail}
          error={dayDetailError}
          loading={dayDetailLoading && dayDetail?.date !== selectedDate}
          onAction={onAction}
          onClose={() => setLensVisible(false)}
          onRetry={onRetryDayDetail}
          preferredUnits={data.preferredUnits}
          visible
        />
      ) : null}
      <MonthSummarySheet
        month={summaryMonth}
        onClose={() => setSummaryMonth(null)}
        preferredUnits={data.preferredUnits}
        summary={summaryMonth ? summariesByMonth.get(monthKey(summaryMonth)) : undefined}
      />
      {filtersOpen ? <FilterSheet filters={filters} onChange={setFilters} onClose={() => setFiltersOpen(false)} visible /> : null}
      {jumpOpen ? (
        <JumpSheet
          error={jumpError}
          onChange={setJumpValue}
          onClose={() => { setJumpOpen(false); setJumpError(null); }}
          onSubmit={jumpToDate}
          value={jumpValue}
          visible
        />
      ) : null}
      {dragState ? (
        <Animated.View pointerEvents="none" style={[styles.sessionDragPreview, ghostStyle]}>
          <View style={styles.sessionDragIcon}>
            <Ionicons color={SLColors.accentViolet} name="barbell-outline" size={18} />
          </View>
          <View style={styles.flex}>
            <Text numberOfLines={1} style={styles.sessionDragTitle}>{dragState.session.title || 'Training Session'}</Text>
            <Text numberOfLines={1} style={styles.sessionDragMeta}>{dragState.targetDate ? `Move to ${formatShortDate(dragState.targetDate)}` : 'Choose a valid date'}</Text>
          </View>
        </Animated.View>
      ) : null}
    </View>
  );
}

type AthleteCalendarDragState = { session: AthleteCalendarSession; targetDate: string | null } | null;

function MonthSection({
  data,
  daysByDate,
  filters,
  month,
  canRescheduleSessions,
  dragState,
  moving,
  onCancelSessionDrag,
  onDragSession,
  onDropSession,
  onOpenSummary,
  onRegisterDropCell,
  onSelectDate,
  onStartSessionDrag,
  reduceMotion,
  selectedDate,
  summary,
  transitionsByWeek,
}: {
  data: AthleteCalendarExperienceData;
  daysByDate: Map<string, AthleteCalendarDay>;
  filters: Set<FilterId>;
  month: Date;
  canRescheduleSessions: boolean;
  dragState: AthleteCalendarDragState;
  moving: boolean;
  onCancelSessionDrag: () => void;
  onDragSession: (absoluteX: number, absoluteY: number) => void;
  onDropSession: (session: AthleteCalendarSession) => void;
  onOpenSummary: () => void;
  onRegisterDropCell: (key: string, date: string, ref: View | null) => void;
  onSelectDate: (date: string) => void;
  onStartSessionDrag: (session: AthleteCalendarSession, absoluteX: number, absoluteY: number) => void;
  reduceMotion: boolean;
  selectedDate: string;
  summary?: AthleteCalendarMonthSummary;
  transitionsByWeek: Map<string, AthleteCalendarBlockTransition[]>;
}) {
  const weeks = athleteCalendarWeeksForMonth(month);
  const context = contextForDate(data.ranges || [], month, data.today);
  const indicator = resolveAthleteCalendarMonthIndicator(summary);
  const transitionCount = [...transitionsByWeek.values()].reduce((total, rows) => total + rows.length, 0);
  const monthHeight = CALENDAR_MONTH_HEIGHT
    + Math.max(0, transitionCount - 1) * CALENDAR_TRANSITION_HEIGHT;
  return (
    <View style={[styles.monthSection, { height: monthHeight }]}>
      <View style={styles.monthSectionHeader}>
        <View style={styles.flex}>
          <Text style={styles.sectionMonth}>{month.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}</Text>
          <Text numberOfLines={1} style={styles.sectionContext}>{context}</Text>
        </View>
        <Pressable accessibilityLabel={`Open ${month.toLocaleDateString(undefined, { month: 'long' })} summary. ${indicator.accessibilityLabel}`} onPress={onOpenSummary} style={styles.summaryBadge}>
          <Text style={styles.summaryRatio}>{indicator.primary}</Text>
          <Text numberOfLines={1} style={styles.summaryLabel}>{indicator.label}</Text>
          {indicator.percent ? <Text style={styles.summaryPercent}>{indicator.percent}</Text> : null}
        </Pressable>
      </View>
      <View style={styles.weekdayRow}>
        {ATHLETE_CALENDAR_WEEKDAYS.map((weekday, index) => (
          <Text key={`${weekday}-${index}`} style={[styles.calendarColumn, styles.weekday]}>{weekday}</Text>
        ))}
      </View>
      <View style={styles.monthGrid}>
        {weeks.map((week) => {
          const weekStartDate = toYmd(week[0]);
          const transitions = transitionsByWeek.get(weekStartDate) || [];
          return (
            <React.Fragment key={weekStartDate}>
              {transitions.map((transition) => (
                <BlockTransitionRow key={transition.key} transition={transition} />
              ))}
              <View style={styles.weekRow}>
                {week.map((date) => {
                  const dateKey = toYmd(date);
                  const day = daysByDate.get(dateKey);
                  const inMonth = date.getMonth() === month.getMonth() && date.getFullYear() === month.getFullYear();
                  const validDropTarget = !!dragState && !!day && isAthleteCalendarDropTargetValid({
                    session: dragState.session,
                    destinationDate: dateKey,
                    today: data.today,
                  });
                  return (
                    <DayCell
                      canRescheduleSessions={canRescheduleSessions}
                      date={dateKey}
                      day={day}
                      dragState={dragState}
                      filtered={day ? !dayMatchesActiveFilters(day, filters) : false}
                      inMonth={inMonth}
                      isToday={dateKey === data.today}
                      key={dateKey}
                      moving={moving}
                      onCancelSessionDrag={onCancelSessionDrag}
                      onDragSession={onDragSession}
                      onDropSession={onDropSession}
                      onPress={() => onSelectDate(dateKey)}
                      onRegister={(ref) => onRegisterDropCell(`${monthKey(month)}:${dateKey}`, dateKey, day ? ref : null)}
                      onStartSessionDrag={onStartSessionDrag}
                      reduceMotion={reduceMotion}
                      selected={dateKey === selectedDate}
                      validDropTarget={validDropTarget}
                      value={date.getDate()}
                    />
                  );
                })}
              </View>
            </React.Fragment>
          );
        })}
      </View>
      {!transitionCount ? <View style={styles.transitionSpacer} /> : null}
    </View>
  );
}

function BlockTransitionRow({ transition }: { transition: AthleteCalendarBlockTransition }) {
  return (
    <View style={styles.transitionRow}>
      <View style={styles.transitionRule} />
      <View style={styles.transitionCopy}>
        <Text numberOfLines={1} style={styles.transitionText}>NEW BLOCK · {transition.blockName.toUpperCase()}</Text>
        <Text style={styles.transitionDate}>STARTS {formatAthleteCalendarBlockStartDate(transition.startDate)}</Text>
      </View>
      <View style={styles.transitionRule} />
    </View>
  );
}

function DayCell({ canRescheduleSessions, date, day, dragState, filtered, inMonth, isToday, moving, onCancelSessionDrag, onDragSession, onDropSession, onPress, onRegister, onStartSessionDrag, reduceMotion, selected, validDropTarget, value }: {
  canRescheduleSessions: boolean;
  date: string;
  day?: AthleteCalendarDay;
  dragState: AthleteCalendarDragState;
  filtered: boolean;
  inMonth: boolean;
  isToday: boolean;
  moving: boolean;
  onCancelSessionDrag: () => void;
  onDragSession: (absoluteX: number, absoluteY: number) => void;
  onDropSession: (session: AthleteCalendarSession) => void;
  onPress: () => void;
  onRegister: (ref: View | null) => void;
  onStartSessionDrag: (session: AthleteCalendarSession, absoluteX: number, absoluteY: number) => void;
  reduceMotion: boolean;
  selected: boolean;
  validDropTarget: boolean;
  value: number;
}) {
  const state = resolveCalendarLensState({
    sessionStatuses: day?.sessions.map((session) => session.status),
    personalItemCount: day?.personalEvents?.length,
    checkInCount: day?.checkIns?.length,
    meetCount: day?.meets?.length,
  });
  const tone = toneColor(primaryCalendarDayTone({
    sessionStatuses: day?.sessions.map((session) => session.status),
    personalItemCount: day?.personalEvents?.length,
    checkInCount: day?.checkIns?.length,
    meetCount: day?.meets?.length,
  }));
  const session = day?.sessions[0];
  const prCount = (day?.sessions || []).reduce((total, item) => total + Number(item.prCount || 0), 0);
  const label = cellLabel(session?.title, state);
  const hasEvidence = Boolean(day && (day.sessions.length || day.personalEvents?.length || day.meets?.length || day.checkIns?.length));
  const movable = !!session && canRescheduleSessions && isAthleteCalendarSessionMovable(session) && !moving;
  return (
    <Pressable
      accessibilityLabel={`${value}. ${label || (hasEvidence ? 'Calendar items' : 'Recovery day')}`}
      accessibilityHint={movable ? 'Long press, then drag onto today or a future Calendar day to reschedule.' : undefined}
      accessibilityState={{ disabled: !!dragState && !validDropTarget, selected }}
      disabled={!!dragState}
      onPress={onPress}
      ref={onRegister}
      style={[
        styles.calendarColumn,
        styles.dayCell,
        selected && styles.dayCellSelected,
        !inMonth && !dragState && styles.dayCellOutside,
        filtered && !dragState && styles.dayCellFiltered,
        dragState && !validDropTarget && styles.dayCellDragInvalid,
        validDropTarget && styles.dayCellDragValid,
        dragState?.targetDate === date && styles.dayCellDragTarget,
      ]}
    >
      {selected ? <LinearGradient colors={['rgba(153,82,255,0.28)', 'rgba(41,20,59,0.10)']} style={StyleSheet.absoluteFillObject} /> : null}
      <View style={styles.dayNumberRow}>
        <Text style={[styles.dayNumber, isToday && styles.dayNumberToday, !inMonth && styles.dayNumberOutside]}>{value}</Text>
        {prCount > 0 ? <Text style={styles.prMarker}>✦</Text> : null}
      </View>
      {label && !filtered && session ? (
        <DraggableSessionPill
          movable={movable}
          onCancel={onCancelSessionDrag}
          onDrag={onDragSession}
          onDrop={() => onDropSession(session)}
          onStart={(absoluteX, absoluteY) => onStartSessionDrag(session, absoluteX, absoluteY)}
          reduceMotion={reduceMotion}
          tone={tone}
        >
          {label}
        </DraggableSessionPill>
      ) : null}
      {!label && day?.personalEvents?.length && !filtered ? <View style={styles.personalRing} /> : null}
      {!hasEvidence && inMonth ? <View style={styles.recoveryDot} /> : null}
      {day && day.sessions.length > 1 && !filtered ? <View style={styles.multiDot}><Text style={styles.multiDotText}>+{day.sessions.length - 1}</Text></View> : null}
    </Pressable>
  );
}

function DraggableSessionPill({ children, movable, onCancel, onDrag, onDrop, onStart, reduceMotion, tone }: {
  children: string;
  movable: boolean;
  onCancel: () => void;
  onDrag: (absoluteX: number, absoluteY: number) => void;
  onDrop: () => void;
  onStart: (absoluteX: number, absoluteY: number) => void;
  reduceMotion: boolean;
  tone: string;
}) {
  const scale = useSharedValue(1);
  const opacity = useSharedValue(1);
  const gesture = Gesture.Pan()
    .enabled(movable)
    .activateAfterLongPress(320)
    .minDistance(3)
    .runOnJS(true)
    .onStart((event) => {
      scale.value = reduceMotion ? 1 : withSpring(1.04);
      opacity.value = 0.3;
      onStart(event.absoluteX, event.absoluteY);
    })
    .onUpdate((event) => onDrag(event.absoluteX, event.absoluteY))
    .onEnd(onDrop)
    .onFinalize((_event, success) => {
      scale.value = reduceMotion ? 1 : withSpring(1);
      opacity.value = 1;
      if (!success) onCancel();
    });
  const animatedStyle = useAnimatedStyle(() => ({ opacity: opacity.value, transform: [{ scale: scale.value }] }));
  return (
    <GestureDetector gesture={gesture}>
      <Animated.View style={[styles.cellPill, { borderColor: `${tone}99`, backgroundColor: `${tone}1C` }, animatedStyle]}>
        <Text numberOfLines={1} style={[styles.cellPillText, { color: tone }]}>{children}</Text>
      </Animated.View>
    </GestureDetector>
  );
}

function DayLens({ canRescheduleSessions, detail, error, loading, onAction, onClose, onRetry, preferredUnits = 'lb', visible }: {
  canRescheduleSessions: boolean;
  detail: AthleteCalendarDayDetail;
  error?: string | null;
  loading: boolean;
  onAction: (action: AthleteCalendarAction) => void;
  onClose: () => void;
  onRetry?: () => void;
  preferredUnits?: 'kg' | 'lb';
  visible: boolean;
}) {
  const primary = detail.sessions[0];
  const state = detail.state;
  const tone = lensColor(state);
  const isRecovery = !detail.sessions.length && state === 'rest';
  const title = primary?.title || (state === 'personal' ? 'Personal Day' : 'Recovery Day');
  const status = primary ? resolveCalendarSessionStatus(primary.status) : null;
  const blockContext = detail.blockContext;
  const dispatchAfterClosingLens = (action: AthleteCalendarAction) => {
    onClose();
    requestAnimationFrame(() => onAction(action));
  };
  const openSessionAfterClosingLens = (id: number) => {
    dispatchAfterClosingLens({ type: 'session', id });
  };
  const openScheduleAfterClosingLens = (session: AthleteCalendarSession) => {
    dispatchAfterClosingLens({ type: 'schedule-session', session });
  };
  return (
    <StrengthLedgerSheetModalAdapter animationType="slide" onRequestClose={onClose} transparent visible={visible}>
      <View style={styles.modalBackdrop}>
        <Pressable accessibilityLabel="Close day detail" onPress={onClose} style={StyleSheet.absoluteFillObject} />
        <View accessibilityViewIsModal style={[styles.daySheet, { borderColor: `${tone}77` }]}>
          <StrengthLedgerSheetDragRegion><View style={styles.sheetHandle} /></StrengthLedgerSheetDragRegion>
          <ScrollView contentContainerStyle={styles.daySheetContent} showsVerticalScrollIndicator={false}>
            <ImageBackground imageStyle={styles.heroImage} source={isRecovery ? RECOVERY_ART : TRAINING_ART} style={styles.dayHero}>
              <LinearGradient colors={['rgba(3,3,7,0.20)', 'rgba(3,3,7,0.78)', SLColors.surfaceInset]} style={StyleSheet.absoluteFillObject} />
              <View style={styles.dayHeroTopRow}>
                <Text style={styles.dayDate}>{formatFullDate(detail.date)}</Text>
                <View style={[styles.statusBadge, { borderColor: `${tone}AA`, backgroundColor: `${tone}22` }]}><Text style={[styles.statusBadgeText, { color: tone }]}>{status?.label || (state === 'personal' ? 'PERSONAL' : 'RECOVERY')}</Text></View>
              </View>
              <View style={styles.dayHeroBottom}>
                <Text style={styles.dayTitle}>{title}</Text>
                {primary?.planned ? <Text style={styles.dayMeta}>{primary.planned.movementCount} movements · {primary.planned.plannedSets} sets</Text> : null}
                {blockContext ? <Text style={styles.dayContext}>{blockContext.name || 'Training block'}{blockContext.weekNumber ? ` · Week ${blockContext.weekNumber}${blockContext.totalWeeks ? ` of ${blockContext.totalWeeks}` : ''}` : ''}</Text> : null}
              </View>
            </ImageBackground>

            {loading ? <View style={styles.loadingPanel}><ActivityIndicator color={SLColors.accentViolet} /><Text style={styles.loadingText}>Loading day evidence…</Text></View> : null}
            {error ? <Pressable onPress={onRetry} style={styles.errorPanel}><Text style={styles.errorText}>{error}</Text><Text style={styles.errorAction}>Retry</Text></Pressable> : null}
            {!loading && !error ? (
              <>
                {isRecovery ? <RecoveryLens detail={detail} onAction={dispatchAfterClosingLens} preferredUnits={preferredUnits} /> : null}
                {primary && status?.lifecycle !== 'completed' ? <TrainingLens onAction={dispatchAfterClosingLens} session={primary} /> : null}
                {primary && canRescheduleSessions && isAthleteCalendarSessionMovable(primary) ? (
                  <Pressable accessibilityRole="button" onPress={() => openScheduleAfterClosingLens(primary)} style={styles.secondaryAction}>
                    <Ionicons color={SLColors.iconMuted} name="calendar-outline" size={18} />
                    <Text style={styles.secondaryActionText}>Manage Session schedule</Text>
                  </Pressable>
                ) : null}
                {primary && status?.lifecycle === 'completed' ? <CompletedLens onOpenSession={openSessionAfterClosingLens} preferredUnits={preferredUnits} session={primary} /> : null}
                {detail.sessions.slice(1).map((session) => <AdditionalSession canReschedule={canRescheduleSessions} key={session.id} onAction={dispatchAfterClosingLens} onSchedule={openScheduleAfterClosingLens} session={session} />)}
                {detail.personalEvents.length ? <PersonalItems events={detail.personalEvents} onAction={dispatchAfterClosingLens} /> : null}
                {!detail.sessions.length && !isRecovery && !detail.personalEvents.length ? <EmptyDay /> : null}
                {detail.capabilities.canAddPersonalItem ? (
                  <Pressable onPress={() => dispatchAfterClosingLens({ type: 'add-event', date: detail.date })} style={styles.secondaryAction}>
                    <Ionicons color={SLColors.iconMuted} name="add" size={18} />
                    <Text style={styles.secondaryActionText}>Add personal item</Text>
                  </Pressable>
                ) : null}
              </>
            ) : null}
          </ScrollView>
        </View>
      </View>
    </StrengthLedgerSheetModalAdapter>
  );
}

function RecoveryLens({ detail, onAction, preferredUnits }: { detail: AthleteCalendarDayDetail; onAction: (action: AthleteCalendarAction) => void; preferredUnits: 'kg' | 'lb' }) {
  const readiness = detail.readiness;
  return (
    <>
      <View style={styles.evidenceCard}>
        <Text style={styles.cardEyebrow}>READINESS</Text>
        {readiness ? (
          <>
            <View style={styles.readinessHeadline}>
              <Text style={styles.readinessValue}>{readiness.score != null ? `${Math.round(readiness.score * 10) / 10}/10` : 'RECORDED'}</Text>
              <Text style={styles.readinessState}>{"TODAY'S CHECK-IN"}</Text>
            </View>
            <View style={styles.readinessGrid}>
              <EvidenceMetric label="ENERGY" value={scoreLabel(readiness.energy)} />
              <EvidenceMetric label="SORENESS" value={scoreLabel(readiness.soreness, true)} />
              <EvidenceMetric label="STRESS" value={scoreLabel(readiness.stress, true)} />
              {readiness.bodyweightKg != null ? <EvidenceMetric label="BODYWEIGHT" value={formatWeight(readiness.bodyweightKg, preferredUnits)} /> : null}
            </View>
          </>
        ) : (
          <>
            <Text style={styles.notSubmitted}>Not submitted</Text>
            <Text style={styles.cardBody}>How are you feeling today?</Text>
            {detail.isToday ? (
              <Pressable onPress={() => onAction({ type: 'daily-readiness', date: detail.date })} style={styles.readinessAction}>
                <Text style={styles.readinessActionText}>Check In</Text>
                <Ionicons color={SLColors.textStrong} name="arrow-forward" size={18} />
              </Pressable>
            ) : <Text style={styles.historicalNote}>No readiness evidence was recorded for this day.</Text>}
          </>
        )}
      </View>
      {detail.nextUp ? (
        <Pressable onPress={() => onAction({ type: 'session', id: detail.nextUp!.id })} style={styles.nextUpCard}>
          <View style={styles.flex}>
            <Text style={styles.cardEyebrow}>NEXT UP</Text>
            <Text style={styles.nextUpTitle}>{detail.nextUp.title || 'Training Session'}</Text>
            <Text style={styles.cardBody}>{relativeDateLabel(detail.date, detail.nextUp.date || '')}{detail.nextUp.blockName ? ` · ${detail.nextUp.blockName}` : ''}</Text>
          </View>
          <Ionicons color={SLColors.accentMuted} name="arrow-forward" size={22} />
        </Pressable>
      ) : null}
    </>
  );
}

function TrainingLens({ onAction, session }: { onAction: (action: AthleteCalendarAction) => void; session: AthleteCalendarDayDetailSession }) {
  const status = resolveCalendarSessionStatus(session.status);
  const movements = session.planned?.movementLabels || session.primaryLifts || [];
  return (
    <>
      <View style={styles.evidenceCard}>
        <Text style={styles.cardEyebrow}>SESSION PREVIEW</Text>
        {movements.slice(0, 3).map((movement, index) => (
          <View key={`${movement}-${index}`} style={styles.movementPreviewRow}>
            <Text style={styles.movementIndex}>{index + 1}</Text>
            <View style={styles.flex}><Text style={styles.movementName}>{movement}</Text>{index === 0 && session.planned?.label ? <Text numberOfLines={1} style={styles.movementMeta}>{session.planned.label}</Text> : null}</View>
          </View>
        ))}
        {Math.max(0, (session.planned?.movementCount || movements.length) - 3) > 0 ? <Text style={styles.moreMovements}>+ {Math.max(0, (session.planned?.movementCount || movements.length) - 3)} more movements</Text> : null}
      </View>
      {session.programmingNotes ? <View style={styles.notesCard}><Text style={styles.cardEyebrow}>COACH NOTES</Text><Text style={styles.notesText}>{session.programmingNotes}</Text></View> : null}
      <PrimaryAction label={status.lifecycle === 'in_progress' ? 'Resume Session' : 'Open Session'} onPress={() => onAction({ type: 'session', id: session.id })} tone={status.lifecycle === 'in_progress' ? 'violet' : 'gold'} />
    </>
  );
}

function CompletedLens({ onOpenSession, preferredUnits, session }: { onOpenSession: (id: number) => void; preferredUnits: 'kg' | 'lb'; session: AthleteCalendarDayDetailSession }) {
  const performance = session.performance;
  const accomplishment = session.accomplishment;
  const best = performance?.bestSet;
  return (
    <>
      <View style={styles.evidenceCard}>
        <Text style={styles.cardEyebrow}>HIGHLIGHTS</Text>
        <View style={styles.highlightGrid}>
          <EvidenceMetric label="PRS" value={String(accomplishment?.count || 0)} />
          <EvidenceMetric label="RPE" value={session.reflection?.sessionRpe != null ? String(session.reflection.sessionRpe) : '—'} />
          <EvidenceMetric label="SETS" value={String(performance?.completedSets || 0)} />
          <EvidenceMetric label="VOLUME" value={performance?.totalVolumeKg ? formatCompactWeight(performance.totalVolumeKg, preferredUnits) : '—'} />
        </View>
      </View>
      {best ? (
        <View style={styles.evidenceCard}>
          <Text style={styles.cardEyebrow}>TOP LIFT</Text>
          <View style={styles.bestLiftRow}>
            <View style={styles.flex}>
              <Text style={styles.bestLiftName}>{accomplishment?.highestPriority?.movementLabel || session.planned?.movementLabels?.[0] || 'Best Set'}</Text>
              <Text style={styles.bestLiftValue}>{formatWeight(best.weightKg, preferredUnits)} × {best.reps}{best.rpe != null ? ` @ ${best.rpe}` : ''}</Text>
            </View>
            {accomplishment?.count ? <View style={styles.prBadge}><Text style={styles.prBadgeText}>PR</Text></View> : null}
          </View>
        </View>
      ) : null}
      <PrimaryAction label="View Session Recap" onPress={() => onOpenSession(session.id)} tone="green" />
    </>
  );
}

function AdditionalSession({ canReschedule, onAction, onSchedule, session }: { canReschedule: boolean; onAction: (action: AthleteCalendarAction) => void; onSchedule: (session: AthleteCalendarSession) => void; session: AthleteCalendarDayDetailSession }) {
  const status = resolveCalendarSessionStatus(session.status);
  return (
