import { KeyboardModal as Modal, KeyboardScrollView as ScrollView } from '@/components/keyboard/KeyboardSurface';
import { StrengthLedgerSheetModalAdapter, StrengthLedgerSheetDragRegion } from '@/components/sheets/StrengthLedgerBottomSheet';
import { Ionicons } from '@expo/vector-icons';
import * as Haptics from 'expo-haptics';
import { LinearGradient } from 'expo-linear-gradient';
import React, { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { ActivityIndicator, FlatList, ImageBackground, Pressable, RefreshControl, StyleSheet, View, type ListRenderItemInfo, type NativeScrollEvent, type NativeSyntheticEvent, type ViewToken } from 'react-native';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import Animated, { useAnimatedStyle, useSharedValue, withSpring } from 'react-native-reanimated';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { TextInput, Text  } from '@/components/ui/sl-text';
import { SLColors, SLFontFamilies, SLRadius, SLTypography } from '@/constants/theme';
import {
  parseYmd,
  toYmd,
  type AthleteCalendarAction,
  type AthleteCalendarDay,
  type AthleteCalendarDayDetail,
  type AthleteCalendarDayDetailSession,
  type AthleteCalendarExperienceData,
  type AthleteCalendarMonthSummary,
  type AthleteCalendarPersonalEvent,
  type AthleteCalendarRange,
  type AthleteCalendarSession,
} from '@/components/calendar/AthleteCalendarExperience';
import { primaryCalendarDayTone, resolveCalendarLensState } from '@/lib/athlete-calendar-lens';
import { resolveAthleteCalendarMonthIndicator } from '@/lib/athlete-calendar-month-summary';
import {
  ATHLETE_CALENDAR_WEEKDAYS,
  athleteCalendarBlockTransitionsForMonth,
  athleteCalendarWeeksForMonth,
  formatAthleteCalendarBlockStartDate,
  type AthleteCalendarBlockTransition,
} from '@/lib/athlete-calendar-grid';
import { createCalendarBoundaryGuard } from '@/lib/calendar-range-pagination';
import {
  athleteCalendarDateAtPoint,
  isAthleteCalendarDropTargetValid,
  isAthleteCalendarSessionMovable,
  type AthleteCalendarDropCell,
} from '@/lib/athlete-calendar-reschedule';
import { resolveCalendarSessionStatus } from '@/lib/calendar-session-status';

const CALENDAR_MONTH_HEIGHT = 511;
const CALENDAR_TRANSITION_HEIGHT = 32;
const CALENDAR_INITIAL_MONTHS = 1;
const CALENDAR_RENDER_BATCH = 1;
const CALENDAR_WINDOW_SIZE = 3;
const TRAINING_ART = require('@/assets/images/gym_vibe.jpg');
const RECOVERY_ART = require('@/assets/images/gym_vibe.jpg');

type FilterId = 'sessions' | 'personal' | 'completed' | 'attention';

const EMPTY_BLOCK_TRANSITIONS = new Map<string, AthleteCalendarBlockTransition[]>();

type Props = {
  anchorMonth: Date;
  data: AthleteCalendarExperienceData;
  onAction: (action: AthleteCalendarAction) => void;
  onMonthChange: (month: Date) => void;
  onToday: () => string | void;
  onShareWeek?: () => void;
  canManagePersonalEvents?: boolean;
  canRescheduleSessions?: boolean;
  onMoveSession?: (session: AthleteCalendarSession, date: string) => void;
  rescheduleBusy?: boolean;
  reduceMotion?: boolean;
  onLoadMore?: () => void;
  onLoadPrevious?: () => void;
  loadingMore?: boolean;
  loadingPrevious?: boolean;
  paginationError?: string | null;
  onRetryLoadMore?: () => void;
  onRefresh?: () => void;
  refreshing?: boolean;
  navigationRevision?: number;
  dayDetail?: AthleteCalendarDayDetail | null;
  dayDetailError?: string | null;
  dayDetailLoading?: boolean;
  onRetryDayDetail?: () => void;
  onSelectedDateChange?: (date: string) => void;
  selectedDate: string;
  initialLensVisible?: boolean;
  initialSummaryMonth?: Date | null;
};

export function AthleteCalendarStoryboardV2({
  anchorMonth,
  canManagePersonalEvents = true,
  canRescheduleSessions = false,
  data,
  dayDetail,
  dayDetailError,
  dayDetailLoading = false,
  loadingMore = false,
  loadingPrevious = false,
  navigationRevision = 0,
  onAction,
  onLoadMore,
  onLoadPrevious,
  onMonthChange,
  onMoveSession,
  onRefresh,
  onRetryDayDetail,
  onRetryLoadMore,
  onSelectedDateChange,
  onToday,
  onShareWeek,
  paginationError,
  refreshing = false,
  rescheduleBusy = false,
  reduceMotion = false,
  selectedDate,
  initialLensVisible = false,
  initialSummaryMonth = null,
}: Props) {
  const insets = useSafeAreaInsets();
  const listRef = useRef<FlatList<Date>>(null);
  const positionedAnchorRef = useRef('');
  const previousBoundaryRef = useRef(createCalendarBoundaryGuard()).current;
  const nextBoundaryRef = useRef(createCalendarBoundaryGuard()).current;
  const [visibleMonth, setVisibleMonth] = useState(() => startOfMonth(anchorMonth));
  const [lensVisible, setLensVisible] = useState(initialLensVisible);
  const [summaryMonth, setSummaryMonth] = useState<Date | null>(initialSummaryMonth);
  const [searchOpen, setSearchOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [filters, setFilters] = useState<Set<FilterId>>(new Set());
  const [jumpOpen, setJumpOpen] = useState(false);
  const [jumpValue, setJumpValue] = useState(selectedDate);
  const [jumpError, setJumpError] = useState<string | null>(null);
  const rootRef = useRef<View | null>(null);
  const cellRefs = useRef(new Map<string, { date: string; ref: View }>());
  const cellRects = useRef(new Map<string, AthleteCalendarDropCell>());
  const rootOrigin = useRef({ x: 0, y: 0 });
  const latestDragPoint = useRef({ x: 0, y: 0 });
  const dragStateRef = useRef<AthleteCalendarDragState>(null);
  const dragX = useSharedValue(0);
  const dragY = useSharedValue(0);
  const dragScale = useSharedValue(1);
  const [dragState, setDragState] = useState<AthleteCalendarDragState>(null);

  const months = useMemo(() => monthsForDays(data.days, anchorMonth), [anchorMonth, data.days]);
  const anchorIndex = useMemo(
    () => Math.max(0, months.findIndex((month) => monthKey(month) === monthKey(anchorMonth))),
    [anchorMonth, months],
  );
  const daysByDate = useMemo(() => new Map(data.days.map((day) => [day.date, day])), [data.days]);
  const summariesByMonth = useMemo(
    () => new Map((data.monthSummaries || []).map((summary) => [summary.month, summary])),
    [data.monthSummaries],
  );
  const transitionsByMonth = useMemo(
    () => new Map(months.map((month) => [
      monthKey(month),
      athleteCalendarBlockTransitionsForMonth(data.ranges || [], month),
    ])),
    [data.ranges, months],
  );
  const monthLayouts = useMemo(() => {
    let offset = 0;
    return months.map((month, index) => {
      const transitions = transitionsByMonth.get(monthKey(month));
      const transitionCount = transitions
        ? [...transitions.values()].reduce((total, rows) => total + rows.length, 0)
        : 0;
      const length = CALENDAR_MONTH_HEIGHT
        + Math.max(0, transitionCount - 1) * CALENDAR_TRANSITION_HEIGHT;
      const layout = { index, length, offset };
      offset += length;
      return layout;
    });
  }, [months, transitionsByMonth]);

  const anchorKey = monthKey(anchorMonth);
  useEffect(() => {
    setVisibleMonth(startOfMonth(anchorMonth));
    if (!months.length || positionedAnchorRef.current === anchorKey) return;
    positionedAnchorRef.current = anchorKey;
    requestAnimationFrame(() => listRef.current?.scrollToIndex({ index: anchorIndex, animated: navigationRevision > 0, viewPosition: 0 }));
  }, [anchorIndex, anchorKey, anchorMonth, months.length, navigationRevision]);

  const viewabilityConfig = useRef({ itemVisiblePercentThreshold: 52, minimumViewTime: 80 }).current;
  const onViewableItemsChanged = useRef(({ viewableItems }: { viewableItems: ViewToken<Date>[] }) => {
    const first = viewableItems.find((item) => item.isViewable)?.item;
    if (first instanceof Date) {
      setVisibleMonth((current) => monthKey(current) === monthKey(first) ? current : startOfMonth(first));
    }
  }).current;

  const beginTimelineGesture = useCallback((event: NativeSyntheticEvent<NativeScrollEvent>) => {
    const offsetY = Math.max(0, event.nativeEvent.contentOffset.y);
    previousBoundaryRef.begin(-offsetY);
    nextBoundaryRef.begin(offsetY);
  }, [nextBoundaryRef, previousBoundaryRef]);

  const updateTimelineBoundaries = useCallback((event: NativeSyntheticEvent<NativeScrollEvent>) => {
    const { contentOffset, contentSize, layoutMeasurement } = event.nativeEvent;
    const offsetY = Math.max(0, contentOffset.y);
    const remaining = Math.max(0, contentSize.height - layoutMeasurement.height - offsetY);
    if (previousBoundaryRef.update({ offsetY: -offsetY, remaining: offsetY })) onLoadPrevious?.();
    if (nextBoundaryRef.update({ offsetY, remaining })) onLoadMore?.();
  }, [nextBoundaryRef, onLoadMore, onLoadPrevious, previousBoundaryRef]);

  const endTimelineGesture = useCallback(() => {
    previousBoundaryRef.end();
    nextBoundaryRef.end();
  }, [nextBoundaryRef, previousBoundaryRef]);

  const selectDate = useCallback((date: string) => {
    onSelectedDateChange?.(date);
    setLensVisible(true);
    void Haptics.selectionAsync();
  }, [onSelectedDateChange]);

  const goToday = useCallback(() => {
    const target = onToday() || data.today;
    const parsed = parseYmd(target) || new Date();
    setVisibleMonth(startOfMonth(parsed));
    positionedAnchorRef.current = '';
    onSelectedDateChange?.(target);
    void Haptics.selectionAsync();
  }, [data.today, onSelectedDateChange, onToday]);

  const searchResults = useMemo(() => {
    const normalized = query.trim().toLowerCase();
    if (!normalized) return [];
    return data.days.filter((day) => {
      const values = [
        day.date,
        formatFullDate(day.date),
        ...day.sessions.flatMap((session) => [session.title || '', session.plannedSummary || '', ...(session.primaryLifts || [])]),
        ...(day.personalEvents || []).flatMap((event) => [event.title, event.location || '', event.category || '']),
        ...(day.meets || []).map((meet) => meet.name || ''),
      ];
      return values.some((value) => value.toLowerCase().includes(normalized));
    }).slice(0, 8);
  }, [data.days, query]);

  const jumpToDate = () => {
    const parsed = parseYmd(jumpValue.trim());
    if (!parsed || toYmd(parsed) !== jumpValue.trim()) {
      setJumpError('Use YYYY-MM-DD.');
      return;
    }
    positionedAnchorRef.current = '';
    onSelectedDateChange?.(jumpValue.trim());
    onMonthChange(startOfMonth(parsed));
    setVisibleMonth(startOfMonth(parsed));
    setJumpOpen(false);
    setJumpError(null);
  };

  const activeFilterCount = filters.size;
  const resolvedDetail = dayDetail?.date === selectedDate
    ? dayDetail
    : fallbackDetail(data, selectedDate, canManagePersonalEvents);

  const updateDropTarget = useCallback((absoluteX: number, absoluteY: number) => {
    const active = dragStateRef.current;
    if (!active) return;
    const hoveredDate = athleteCalendarDateAtPoint(absoluteX, absoluteY, cellRects.current.values());
    const targetDate = hoveredDate && isAthleteCalendarDropTargetValid({
      session: active.session,
      destinationDate: hoveredDate,
      today: data.today,
    }) ? hoveredDate : null;
    if (active.targetDate === targetDate) return;
    const next = { ...active, targetDate };
    dragStateRef.current = next;
    setDragState(next);
    if (targetDate) void Haptics.selectionAsync();
  }, [data.today]);

  const refreshDropGeometry = useCallback(() => {
    rootRef.current?.measureInWindow((x, y) => {
      rootOrigin.current = { x, y };
      dragX.value = latestDragPoint.current.x - x;
      dragY.value = latestDragPoint.current.y - y;
    });
    const entries = Array.from(cellRefs.current.entries());
    if (!entries.length) return;
    const measured = new Map<string, AthleteCalendarDropCell>();
    let remaining = entries.length;
    entries.forEach(([key, entry]) => {
      entry.ref.measureInWindow((x, y, width, height) => {
        if (width > 0 && height > 0) measured.set(key, { date: entry.date, x, y, width, height });
        remaining -= 1;
        if (remaining === 0) {
          cellRects.current = measured;
          updateDropTarget(latestDragPoint.current.x, latestDragPoint.current.y);
        }
      });
    });
  }, [dragX, dragY, updateDropTarget]);

  useLayoutEffect(() => {
    const frame = requestAnimationFrame(refreshDropGeometry);
    return () => cancelAnimationFrame(frame);
  }, [months, refreshDropGeometry]);

  const registerDropCell = useCallback((key: string, date: string, ref: View | null) => {
    if (ref) cellRefs.current.set(key, { date, ref });
    else cellRefs.current.delete(key);
  }, []);

  const updateDragPoint = useCallback((absoluteX: number, absoluteY: number) => {
    latestDragPoint.current = { x: absoluteX, y: absoluteY };
    dragX.value = absoluteX - rootOrigin.current.x;
    dragY.value = absoluteY - rootOrigin.current.y;
    updateDropTarget(absoluteX, absoluteY);
  }, [dragX, dragY, updateDropTarget]);

  const startSessionDrag = useCallback((session: AthleteCalendarSession, absoluteX: number, absoluteY: number) => {
    latestDragPoint.current = { x: absoluteX, y: absoluteY };
    const next: AthleteCalendarDragState = { session, targetDate: null };
    dragStateRef.current = next;
    setDragState(next);
    dragScale.value = reduceMotion ? 1 : withSpring(1.03);
    updateDragPoint(absoluteX, absoluteY);
    refreshDropGeometry();
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
  }, [dragScale, reduceMotion, refreshDropGeometry, updateDragPoint]);

  const clearSessionDrag = useCallback(() => {
    dragStateRef.current = null;
    setDragState(null);
    dragScale.value = reduceMotion ? 1 : withSpring(1);
  }, [dragScale, reduceMotion]);

  const finishSessionDrag = useCallback((session: AthleteCalendarSession) => {
    const targetDate = dragStateRef.current?.targetDate || null;
    clearSessionDrag();
    if (targetDate) onMoveSession?.(session, targetDate);
  }, [clearSessionDrag, onMoveSession]);

  const ghostStyle = useAnimatedStyle(() => ({
    transform: [
      { translateX: dragX.value - 96 },
      { translateY: dragY.value - 27 },
      { scale: dragScale.value },
    ],
  }));

  const renderMonth = ({ item }: ListRenderItemInfo<Date>) => (
    <MonthSection
      data={data}
      daysByDate={daysByDate}
      filters={filters}
      month={item}
      onOpenSummary={() => setSummaryMonth(item)}
      onCancelSessionDrag={clearSessionDrag}
      onDragSession={updateDragPoint}
      onDropSession={finishSessionDrag}
      onRegisterDropCell={registerDropCell}
      onSelectDate={selectDate}
      onStartSessionDrag={startSessionDrag}
      canRescheduleSessions={canRescheduleSessions}
      dragState={dragState}
      moving={rescheduleBusy}
      reduceMotion={reduceMotion}
      selectedDate={selectedDate}
      summary={summariesByMonth.get(monthKey(item))}
      transitionsByWeek={transitionsByMonth.get(monthKey(item)) || EMPTY_BLOCK_TRANSITIONS}
    />
  );

  return (
    <View onLayout={() => requestAnimationFrame(refreshDropGeometry)} ref={rootRef} style={styles.root}>
      <LinearGradient colors={['rgba(109,42,184,0.10)', 'rgba(2,2,5,0)', 'rgba(2,2,5,0)']} pointerEvents="none" style={StyleSheet.absoluteFillObject} />
      <View style={styles.compactHeader}>
        <Pressable accessibilityRole="button" onPress={() => { setJumpValue(toYmd(visibleMonth)); setJumpOpen(true); }} style={styles.timeHeaderCopy}>
          <Text style={styles.monthTitle}>CALENDAR</Text>
          <Text numberOfLines={1} style={styles.monthContext}>
            {visibleMonth.toLocaleDateString(undefined, { month: 'short', year: 'numeric' }).toUpperCase()} · JUMP TO DATE
          </Text>
        </Pressable>
        <View style={styles.headerActions}>
          <UtilityButton icon="search" label="Search Calendar" onPress={() => setSearchOpen((value) => !value)} />
          <UtilityButton badge={activeFilterCount || undefined} icon="options-outline" label="Filter Calendar" onPress={() => setFiltersOpen(true)} />
          {canManagePersonalEvents ? <UtilityButton icon="add" label="Add personal item" onPress={() => onAction({ type: 'add-event', date: selectedDate })} /> : null}
        </View>
      </View>

      {onShareWeek ? <Pressable accessibilityRole="button" accessibilityLabel="Share training week" onPress={onShareWeek} style={styles.weekReportAction}><Ionicons name="document-text-outline" color={SLColors.accentMuted} size={17} /><Text style={styles.weekReportLabel}>Share training week</Text><Ionicons name="chevron-forward" color={SLColors.accentMuted} size={14} /></Pressable> : null}

      {searchOpen ? (
        <View style={styles.searchSurface}>
          <View style={styles.searchInputRow}>
            <Ionicons color={SLColors.iconMuted} name="search" size={18} />
            <TextInput
              autoFocus
              onChangeText={setQuery}
              placeholder="Sessions, dates, movements, personal items"
              placeholderTextColor={SLColors.textMuted}
              style={styles.searchInput}
              value={query}
            />
            <Pressable hitSlop={10} onPress={() => { setQuery(''); setSearchOpen(false); }}>
              <Ionicons color={SLColors.iconMuted} name="close" size={19} />
            </Pressable>
          </View>
          {query.trim() ? (
            <View style={styles.searchResults}>
              {searchResults.length ? searchResults.map((day) => (
                <Pressable key={day.date} onPress={() => { setSearchOpen(false); setQuery(''); selectDate(day.date); }} style={styles.searchResultRow}>
                  <Text style={styles.searchResultDate}>{formatShortDate(day.date)}</Text>
                  <Text numberOfLines={1} style={styles.searchResultTitle}>{searchResultTitle(day)}</Text>
                  <Ionicons color={SLColors.iconMuted} name="chevron-forward" size={17} />
                </Pressable>
              )) : <Text style={styles.emptySearch}>No matching Calendar evidence.</Text>}
            </View>
          ) : null}
        </View>
      ) : null}

      <FlatList
        data={months}
        getItemLayout={(_, index) => monthLayouts[index] || { index, length: CALENDAR_MONTH_HEIGHT, offset: CALENDAR_MONTH_HEIGHT * index }}
        initialNumToRender={CALENDAR_INITIAL_MONTHS}
        initialScrollIndex={anchorIndex}
        keyExtractor={monthKey}
        maintainVisibleContentPosition={{ minIndexForVisible: 0, autoscrollToTopThreshold: 24 }}
        maxToRenderPerBatch={CALENDAR_RENDER_BATCH}
        onMomentumScrollBegin={beginTimelineGesture}
        onMomentumScrollEnd={endTimelineGesture}
        onScroll={updateTimelineBoundaries}
        onScrollBeginDrag={beginTimelineGesture}
        onScrollEndDrag={endTimelineGesture}
        onViewableItemsChanged={onViewableItemsChanged}
        refreshControl={onRefresh ? <RefreshControl enabled={!dragState} refreshing={refreshing} onRefresh={onRefresh} tintColor={SLColors.accentViolet} /> : undefined}
        ref={listRef}
        renderItem={renderMonth}
        scrollEnabled={!dragState}
        scrollEventThrottle={32}
        showsVerticalScrollIndicator={false}
        style={styles.monthList}
        viewabilityConfig={viewabilityConfig}
        windowSize={CALENDAR_WINDOW_SIZE}
        ListHeaderComponent={loadingPrevious ? <ActivityIndicator color={SLColors.accentViolet} style={styles.pageSpinner} /> : null}
        ListFooterComponent={(
          <View style={styles.listFooter}>
            {loadingMore ? <ActivityIndicator color={SLColors.accentViolet} /> : null}
            {paginationError ? (
              <Pressable onPress={onRetryLoadMore} style={styles.retryRow}>
                <Text style={styles.retryText}>More dates could not load. Tap to retry.</Text>
              </Pressable>
            ) : null}
            <View style={{ height: 148 + insets.bottom }} />
          </View>
        )}
      />

      <View pointerEvents="box-none" style={[styles.floatingControls, { bottom: 70 + insets.bottom }]}>
        <Pressable accessibilityRole="button" onPress={goToday} style={styles.todayButton}>
          <Text style={styles.todayText}>Today</Text>
        </Pressable>
      </View>

      {lensVisible ? (
        <DayLens
          canRescheduleSessions={canRescheduleSessions}
          detail={resolvedDetail}
          error={dayDetailError}
          loading={dayDetailLoading && dayDetail?.date !== selectedDate}
          onAction={onAction}
          onClose={() => setLensVisible(false)}
          onRetry={onRetryDayDetail}
          preferredUnits={data.preferredUnits}
          visible
        />
      ) : null}
      <MonthSummarySheet
        month={summaryMonth}
        onClose={() => setSummaryMonth(null)}
        preferredUnits={data.preferredUnits}
        summary={summaryMonth ? summariesByMonth.get(monthKey(summaryMonth)) : undefined}
      />
      {filtersOpen ? <FilterSheet filters={filters} onChange={setFilters} onClose={() => setFiltersOpen(false)} visible /> : null}
      {jumpOpen ? (
        <JumpSheet
          error={jumpError}
          onChange={setJumpValue}
          onClose={() => { setJumpOpen(false); setJumpError(null); }}
          onSubmit={jumpToDate}
          value={jumpValue}
          visible
        />
      ) : null}
      {dragState ? (
        <Animated.View pointerEvents="none" style={[styles.sessionDragPreview, ghostStyle]}>
          <View style={styles.sessionDragIcon}>
            <Ionicons color={SLColors.accentViolet} name="barbell-outline" size={18} />
          </View>
          <View style={styles.flex}>
            <Text numberOfLines={1} style={styles.sessionDragTitle}>{dragState.session.title || 'Training Session'}</Text>
            <Text numberOfLines={1} style={styles.sessionDragMeta}>{dragState.targetDate ? `Move to ${formatShortDate(dragState.targetDate)}` : 'Choose a valid date'}</Text>
          </View>
        </Animated.View>
      ) : null}
    </View>
  );
}

type AthleteCalendarDragState = { session: AthleteCalendarSession; targetDate: string | null } | null;

function MonthSection({
  data,
  daysByDate,
  filters,
  month,
  canRescheduleSessions,
  dragState,
  moving,
  onCancelSessionDrag,
  onDragSession,
  onDropSession,
  onOpenSummary,
  onRegisterDropCell,
  onSelectDate,
  onStartSessionDrag,
  reduceMotion,
  selectedDate,
  summary,
  transitionsByWeek,
}: {
  data: AthleteCalendarExperienceData;
  daysByDate: Map<string, AthleteCalendarDay>;
  filters: Set<FilterId>;
  month: Date;
  canRescheduleSessions: boolean;
  dragState: AthleteCalendarDragState;
  moving: boolean;
  onCancelSessionDrag: () => void;
  onDragSession: (absoluteX: number, absoluteY: number) => void;
  onDropSession: (session: AthleteCalendarSession) => void;
  onOpenSummary: () => void;
  onRegisterDropCell: (key: string, date: string, ref: View | null) => void;
  onSelectDate: (date: string) => void;
  onStartSessionDrag: (session: AthleteCalendarSession, absoluteX: number, absoluteY: number) => void;
  reduceMotion: boolean;
  selectedDate: string;
  summary?: AthleteCalendarMonthSummary;
  transitionsByWeek: Map<string, AthleteCalendarBlockTransition[]>;
}) {
  const weeks = athleteCalendarWeeksForMonth(month);
  const context = contextForDate(data.ranges || [], month, data.today);
  const indicator = resolveAthleteCalendarMonthIndicator(summary);
  const transitionCount = [...transitionsByWeek.values()].reduce((total, rows) => total + rows.length, 0);
  const monthHeight = CALENDAR_MONTH_HEIGHT
    + Math.max(0, transitionCount - 1) * CALENDAR_TRANSITION_HEIGHT;
  return (
    <View style={[styles.monthSection, { height: monthHeight }]}>
      <View style={styles.monthSectionHeader}>
        <View style={styles.flex}>
          <Text style={styles.sectionMonth}>{month.toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}</Text>
          <Text numberOfLines={1} style={styles.sectionContext}>{context}</Text>
        </View>
        <Pressable accessibilityLabel={`Open ${month.toLocaleDateString(undefined, { month: 'long' })} summary. ${indicator.accessibilityLabel}`} onPress={onOpenSummary} style={styles.summaryBadge}>
          <Text style={styles.summaryRatio}>{indicator.primary}</Text>
          <Text numberOfLines={1} style={styles.summaryLabel}>{indicator.label}</Text>
          {indicator.percent ? <Text style={styles.summaryPercent}>{indicator.percent}</Text> : null}
        </Pressable>
      </View>
      <View style={styles.weekdayRow}>
        {ATHLETE_CALENDAR_WEEKDAYS.map((weekday, index) => (
          <Text key={`${weekday}-${index}`} style={[styles.calendarColumn, styles.weekday]}>{weekday}</Text>
        ))}
      </View>
      <View style={styles.monthGrid}>
        {weeks.map((week) => {
          const weekStartDate = toYmd(week[0]);
          const transitions = transitionsByWeek.get(weekStartDate) || [];
          return (
            <React.Fragment key={weekStartDate}>
              {transitions.map((transition) => (
                <BlockTransitionRow key={transition.key} transition={transition} />
              ))}
              <View style={styles.weekRow}>
                {week.map((date) => {
                  const dateKey = toYmd(date);
                  const day = daysByDate.get(dateKey);
                  const inMonth = date.getMonth() === month.getMonth() && date.getFullYear() === month.getFullYear();
                  const validDropTarget = !!dragState && !!day && isAthleteCalendarDropTargetValid({
                    session: dragState.session,
                    destinationDate: dateKey,
                    today: data.today,
                  });
                  return (
                    <DayCell
                      canRescheduleSessions={canRescheduleSessions}
                      date={dateKey}
                      day={day}
                      dragState={dragState}
                      filtered={day ? !dayMatchesActiveFilters(day, filters) : false}
                      inMonth={inMonth}
                      isToday={dateKey === data.today}
                      key={dateKey}
                      moving={moving}
                      onCancelSessionDrag={onCancelSessionDrag}
                      onDragSession={onDragSession}
                      onDropSession={onDropSession}
                      onPress={() => onSelectDate(dateKey)}
                      onRegister={(ref) => onRegisterDropCell(`${monthKey(month)}:${dateKey}`, dateKey, day ? ref : null)}
                      onStartSessionDrag={onStartSessionDrag}
                      reduceMotion={reduceMotion}
                      selected={dateKey === selectedDate}
                      validDropTarget={validDropTarget}
                      value={date.getDate()}
                    />
                  );
                })}
              </View>
            </React.Fragment>
          );
        })}
      </View>
      {!transitionCount ? <View style={styles.transitionSpacer} /> : null}
    </View>
  );
}

function BlockTransitionRow({ transition }: { transition: AthleteCalendarBlockTransition }) {
  return (
    <View style={styles.transitionRow}>
      <View style={styles.transitionRule} />
      <View style={styles.transitionCopy}>
        <Text numberOfLines={1} style={styles.transitionText}>NEW BLOCK · {transition.blockName.toUpperCase()}</Text>
        <Text style={styles.transitionDate}>STARTS {formatAthleteCalendarBlockStartDate(transition.startDate)}</Text>
      </View>
      <View style={styles.transitionRule} />
    </View>
  );
}

function DayCell({ canRescheduleSessions, date, day, dragState, filtered, inMonth, isToday, moving, onCancelSessionDrag, onDragSession, onDropSession, onPress, onRegister, onStartSessionDrag, reduceMotion, selected, validDropTarget, value }: {
  canRescheduleSessions: boolean;
  date: string;
  day?: AthleteCalendarDay;
  dragState: AthleteCalendarDragState;
  filtered: boolean;
  inMonth: boolean;
  isToday: boolean;
  moving: boolean;
  onCancelSessionDrag: () => void;
  onDragSession: (absoluteX: number, absoluteY: number) => void;
  onDropSession: (session: AthleteCalendarSession) => void;
  onPress: () => void;
  onRegister: (ref: View | null) => void;
  onStartSessionDrag: (session: AthleteCalendarSession, absoluteX: number, absoluteY: number) => void;
  reduceMotion: boolean;
  selected: boolean;
  validDropTarget: boolean;
  value: number;
}) {
  const state = resolveCalendarLensState({
    sessionStatuses: day?.sessions.map((session) => session.status),
    personalItemCount: day?.personalEvents?.length,
    checkInCount: day?.checkIns?.length,
    meetCount: day?.meets?.length,
  });
  const tone = toneColor(primaryCalendarDayTone({
    sessionStatuses: day?.sessions.map((session) => session.status),
    personalItemCount: day?.personalEvents?.length,
    checkInCount: day?.checkIns?.length,
    meetCount: day?.meets?.length,
  }));
  const session = day?.sessions[0];
  const prCount = (day?.sessions || []).reduce((total, item) => total + Number(item.prCount || 0), 0);
  const label = cellLabel(session?.title, state);
  const hasEvidence = Boolean(day && (day.sessions.length || day.personalEvents?.length || day.meets?.length || day.checkIns?.length));
  const movable = !!session && canRescheduleSessions && isAthleteCalendarSessionMovable(session) && !moving;
  return (
    <Pressable
      accessibilityLabel={`${value}. ${label || (hasEvidence ? 'Calendar items' : 'Recovery day')}`}
      accessibilityHint={movable ? 'Long press, then drag onto today or a future Calendar day to reschedule.' : undefined}
      accessibilityState={{ disabled: !!dragState && !validDropTarget, selected }}
      disabled={!!dragState}
      onPress={onPress}
      ref={onRegister}
      style={[
        styles.calendarColumn,
        styles.dayCell,
        selected && styles.dayCellSelected,
        !inMonth && !dragState && styles.dayCellOutside,
        filtered && !dragState && styles.dayCellFiltered,
        dragState && !validDropTarget && styles.dayCellDragInvalid,
        validDropTarget && styles.dayCellDragValid,
        dragState?.targetDate === date && styles.dayCellDragTarget,
      ]}
    >
      {selected ? <LinearGradient colors={['rgba(153,82,255,0.28)', 'rgba(41,20,59,0.10)']} style={StyleSheet.absoluteFillObject} /> : null}
      <View style={styles.dayNumberRow}>
        <Text style={[styles.dayNumber, isToday && styles.dayNumberToday, !inMonth && styles.dayNumberOutside]}>{value}</Text>
        {prCount > 0 ? <Text style={styles.prMarker}>✦</Text> : null}
      </View>
      {label && !filtered && session ? (
        <DraggableSessionPill
          movable={movable}
          onCancel={onCancelSessionDrag}
          onDrag={onDragSession}
          onDrop={() => onDropSession(session)}
          onStart={(absoluteX, absoluteY) => onStartSessionDrag(session, absoluteX, absoluteY)}
          reduceMotion={reduceMotion}
          tone={tone}
        >
          {label}
        </DraggableSessionPill>
      ) : null}
      {!label && day?.personalEvents?.length && !filtered ? <View style={styles.personalRing} /> : null}
      {!hasEvidence && inMonth ? <View style={styles.recoveryDot} /> : null}
      {day && day.sessions.length > 1 && !filtered ? <View style={styles.multiDot}><Text style={styles.multiDotText}>+{day.sessions.length - 1}</Text></View> : null}
    </Pressable>
  );
}

function DraggableSessionPill({ children, movable, onCancel, onDrag, onDrop, onStart, reduceMotion, tone }: {
  children: string;
  movable: boolean;
  onCancel: () => void;
  onDrag: (absoluteX: number, absoluteY: number) => void;
  onDrop: () => void;
  onStart: (absoluteX: number, absoluteY: number) => void;
  reduceMotion: boolean;
  tone: string;
}) {
  const scale = useSharedValue(1);
  const opacity = useSharedValue(1);
  const gesture = Gesture.Pan()
    .enabled(movable)
    .activateAfterLongPress(320)
    .minDistance(3)
    .runOnJS(true)
    .onStart((event) => {
      scale.value = reduceMotion ? 1 : withSpring(1.04);
      opacity.value = 0.3;
      onStart(event.absoluteX, event.absoluteY);
    })
    .onUpdate((event) => onDrag(event.absoluteX, event.absoluteY))
    .onEnd(onDrop)
    .onFinalize((_event, success) => {
      scale.value = reduceMotion ? 1 : withSpring(1);
      opacity.value = 1;
      if (!success) onCancel();
    });
  const animatedStyle = useAnimatedStyle(() => ({ opacity: opacity.value, transform: [{ scale: scale.value }] }));
  return (
    <GestureDetector gesture={gesture}>
      <Animated.View style={[styles.cellPill, { borderColor: `${tone}99`, backgroundColor: `${tone}1C` }, animatedStyle]}>
        <Text numberOfLines={1} style={[styles.cellPillText, { color: tone }]}>{children}</Text>
      </Animated.View>
    </GestureDetector>
  );
}

function DayLens({ canRescheduleSessions, detail, error, loading, onAction, onClose, onRetry, preferredUnits = 'lb', visible }: {
  canRescheduleSessions: boolean;
  detail: AthleteCalendarDayDetail;
  error?: string | null;
  loading: boolean;
  onAction: (action: AthleteCalendarAction) => void;
  onClose: () => void;
  onRetry?: () => void;
  preferredUnits?: 'kg' | 'lb';
  visible: boolean;
}) {
  const primary = detail.sessions[0];
  const state = detail.state;
  const tone = lensColor(state);
  const isRecovery = !detail.sessions.length && state === 'rest';
  const title = primary?.title || (state === 'personal' ? 'Personal Day' : 'Recovery Day');
  const status = primary ? resolveCalendarSessionStatus(primary.status) : null;
  const blockContext = detail.blockContext;
  const dispatchAfterClosingLens = (action: AthleteCalendarAction) => {
    onClose();
    requestAnimationFrame(() => onAction(action));
  };
  const openSessionAfterClosingLens = (id: number) => {
    dispatchAfterClosingLens({ type: 'session', id });
  };
  const openScheduleAfterClosingLens = (session: AthleteCalendarSession) => {
    dispatchAfterClosingLens({ type: 'schedule-session', session });
  };
  return (
    <StrengthLedgerSheetModalAdapter animationType="slide" onRequestClose={onClose} transparent visible={visible}>
      <View style={styles.modalBackdrop}>
        <Pressable accessibilityLabel="Close day detail" onPress={onClose} style={StyleSheet.absoluteFillObject} />
        <View accessibilityViewIsModal style={[styles.daySheet, { borderColor: `${tone}77` }]}>
          <StrengthLedgerSheetDragRegion><View style={styles.sheetHandle} /></StrengthLedgerSheetDragRegion>
          <ScrollView contentContainerStyle={styles.daySheetContent} showsVerticalScrollIndicator={false}>
            <ImageBackground imageStyle={styles.heroImage} source={isRecovery ? RECOVERY_ART : TRAINING_ART} style={styles.dayHero}>
              <LinearGradient colors={['rgba(3,3,7,0.20)', 'rgba(3,3,7,0.78)', SLColors.surfaceInset]} style={StyleSheet.absoluteFillObject} />
              <View style={styles.dayHeroTopRow}>
                <Text style={styles.dayDate}>{formatFullDate(detail.date)}</Text>
                <View style={[styles.statusBadge, { borderColor: `${tone}AA`, backgroundColor: `${tone}22` }]}><Text style={[styles.statusBadgeText, { color: tone }]}>{status?.label || (state === 'personal' ? 'PERSONAL' : 'RECOVERY')}</Text></View>
              </View>
              <View style={styles.dayHeroBottom}>
                <Text style={styles.dayTitle}>{title}</Text>
                {primary?.planned ? <Text style={styles.dayMeta}>{primary.planned.movementCount} movements · {primary.planned.plannedSets} sets</Text> : null}
                {blockContext ? <Text style={styles.dayContext}>{blockContext.name || 'Training block'}{blockContext.weekNumber ? ` · Week ${blockContext.weekNumber}${blockContext.totalWeeks ? ` of ${blockContext.totalWeeks}` : ''}` : ''}</Text> : null}
              </View>
            </ImageBackground>

            {loading ? <View style={styles.loadingPanel}><ActivityIndicator color={SLColors.accentViolet} /><Text style={styles.loadingText}>Loading day evidence…</Text></View> : null}
            {error ? <Pressable onPress={onRetry} style={styles.errorPanel}><Text style={styles.errorText}>{error}</Text><Text style={styles.errorAction}>Retry</Text></Pressable> : null}
            {!loading && !error ? (
              <>
                {isRecovery ? <RecoveryLens detail={detail} onAction={dispatchAfterClosingLens} preferredUnits={preferredUnits} /> : null}
                {primary && status?.lifecycle !== 'completed' ? <TrainingLens onAction={dispatchAfterClosingLens} session={primary} /> : null}
                {primary && canRescheduleSessions && isAthleteCalendarSessionMovable(primary) ? (
                  <Pressable accessibilityRole="button" onPress={() => openScheduleAfterClosingLens(primary)} style={styles.secondaryAction}>
                    <Ionicons color={SLColors.iconMuted} name="calendar-outline" size={18} />
                    <Text style={styles.secondaryActionText}>Manage Session schedule</Text>
                  </Pressable>
                ) : null}
                {primary && status?.lifecycle === 'completed' ? <CompletedLens onOpenSession={openSessionAfterClosingLens} preferredUnits={preferredUnits} session={primary} /> : null}
                {detail.sessions.slice(1).map((session) => <AdditionalSession canReschedule={canRescheduleSessions} key={session.id} onAction={dispatchAfterClosingLens} onSchedule={openScheduleAfterClosingLens} session={session} />)}
                {detail.personalEvents.length ? <PersonalItems events={detail.personalEvents} onAction={dispatchAfterClosingLens} /> : null}
                {!detail.sessions.length && !isRecovery && !detail.personalEvents.length ? <EmptyDay /> : null}
                {detail.capabilities.canAddPersonalItem ? (
                  <Pressable onPress={() => dispatchAfterClosingLens({ type: 'add-event', date: detail.date })} style={styles.secondaryAction}>
                    <Ionicons color={SLColors.iconMuted} name="add" size={18} />
                    <Text style={styles.secondaryActionText}>Add personal item</Text>
                  </Pressable>
                ) : null}
              </>
            ) : null}
          </ScrollView>
        </View>
      </View>
    </StrengthLedgerSheetModalAdapter>
  );
}

function RecoveryLens({ detail, onAction, preferredUnits }: { detail: AthleteCalendarDayDetail; onAction: (action: AthleteCalendarAction) => void; preferredUnits: 'kg' | 'lb' }) {
  const readiness = detail.readiness;
  return (
    <>
      <View style={styles.evidenceCard}>
        <Text style={styles.cardEyebrow}>READINESS</Text>
        {readiness ? (
          <>
            <View style={styles.readinessHeadline}>
              <Text style={styles.readinessValue}>{readiness.score != null ? `${Math.round(readiness.score * 10) / 10}/10` : 'RECORDED'}</Text>
              <Text style={styles.readinessState}>{"TODAY'S CHECK-IN"}</Text>
            </View>
            <View style={styles.readinessGrid}>
              <EvidenceMetric label="ENERGY" value={scoreLabel(readiness.energy)} />
              <EvidenceMetric label="SORENESS" value={scoreLabel(readiness.soreness, true)} />
              <EvidenceMetric label="STRESS" value={scoreLabel(readiness.stress, true)} />
              {readiness.bodyweightKg != null ? <EvidenceMetric label="BODYWEIGHT" value={formatWeight(readiness.bodyweightKg, preferredUnits)} /> : null}
            </View>
          </>
        ) : (
          <>
            <Text style={styles.notSubmitted}>Not submitted</Text>
            <Text style={styles.cardBody}>How are you feeling today?</Text>
            {detail.isToday ? (
              <Pressable onPress={() => onAction({ type: 'daily-readiness', date: detail.date })} style={styles.readinessAction}>
                <Text style={styles.readinessActionText}>Check In</Text>
                <Ionicons color={SLColors.textStrong} name="arrow-forward" size={18} />
              </Pressable>
            ) : <Text style={styles.historicalNote}>No readiness evidence was recorded for this day.</Text>}
          </>
        )}
      </View>
      {detail.nextUp ? (
        <Pressable onPress={() => onAction({ type: 'session', id: detail.nextUp!.id })} style={styles.nextUpCard}>
          <View style={styles.flex}>
