              onPress={onBeginAthleteEdit}
              style={({ pressed }) => [styles.identityAvatarButton, pressed && styles.pressed]}
            >
              <SLProfileAvatar
                accessibilityLabel={`${athleteName || 'Athlete'} profile photo`}
