        <ProgrammingLastExposure context={exposureContext} item={item} displayUnit={displayUnit} onOpenHistory={onOpenHistory} />
        <CoachNotesSection value={draft.notes} editable={editable} onChange={(value) => onChange({ notes: value })} />
