        ...current.movements,
        [selectedId]: { ...current.movements[selectedId], ...patch },
      },
    }));
  }, [selectedId]);

  const changeEditorDisplayUnit = useCallback((unit: CoachDisplayUnit) => {
    if (unit === displayUnit || savingSession) return;
