  }, [displayUnit, props, savingSession]);

  const discardWorkspaceChanges = useCallback(() => {
    setSessionDraft(cloneSessionWorkspaceDraft(incomingSession));
    setPersistedSession(cloneSessionWorkspaceDraft(incomingSession));
