    return () => {
      mounted = false;
      if (subscription) subscription.remove();
    };
  }, [isIndividual, router, user?.id, user?.is_coach, user?.user_id]);

  // Prevent login/dashboard flicker while SecureStore rehydrates, but never stay blank forever.
