            <ThemeProvider value={appOLEDTheme}>
              <MobileEducationProvider>
                <RootStack />
                <OtaUpdateController />
                <StatusBar style="light" />
              </MobileEducationProvider>
            </ThemeProvider>
          </AuthProvider>
        )}
      </AppShell>
    </GestureHandlerRootView>
  );
}

