        return;
      }
      await openRecoverableCheckoutBrowser(checkoutUrl);
      setActivating(false);
      await refreshActivationState({ showMessage: true });
    } catch (err: any) {
      console.warn('Could not start activation', err);
      setError(err?.message || 'Could not start activation. Please try again.');
    } finally {
      setActivating(false);
    }
  };

  const cancelTeamCoachUpgrade = () => {
    Alert.alert(
      'Cancel Team Coach upgrade?',
      'You will return to Athlete. Your identity, training history, and linked coach relationship will remain.',
      [
        { text: 'Keep upgrade', style: 'cancel' },
        {
          text: 'Return to Athlete',
          style: 'destructive',
          onPress: async () => {
            setActivating(true);
            setError(null);
            try {
              const result = await cancelPendingTeamCoachUpgrade();
              const payload = result.json || {};
              if (!result.ok || payload.ok === false) {
                throw new Error(payload.reason || payload.error || 'Could not cancel the upgrade.');
              }
              await refreshAccountState();
              router.replace('/');
            } catch (err: any) {
              setError(err?.message || 'Could not cancel the upgrade.');
            } finally {
              setActivating(false);
            }
          },
        },
      ]
    );
  };

  const simulateActivation = async () => {
    setSimulating(true);
    setError(null);
    try {
      const result = await devSimulateStripeActivation();
      const payload = result.json || {};
      if (!result.ok || payload.ok === false) {
        setError(payload.error || payload.message || 'Could not simulate Stripe activation.');
        return;
      }
      await applyActivationPayload(payload);
    } catch (err: any) {
      setError(err?.message || 'Network error. Please try again.');
    } finally {
      setSimulating(false);
    }
  };

  return (
    <SafeAreaView style={styles.gateScreen}>
    <ScrollView contentContainerStyle={styles.gateContent}>
      <Image
        source={require('@/assets/images/16:9.png')}
        style={styles.gateLogo}
        resizeMode="contain"
      />
      <View style={styles.gatePanel}>
