              <SLButton
                fullWidth
                label={authMode === 'signup' ? 'Create account and continue' : 'Sign in'}
                variant="secondary"
                onPress={authMode === 'signup' ? handleSignup : handleLogin}
                disabled={loading || (authMode === 'signup' && !canSubmitSignup)}
