                    >
                      <Text style={[styles.roleOptionText, setupRole === 'self_coach' && styles.roleOptionTextActive]}>
                        Self-Coach
                      </Text>
                    </Pressable>
                  </View>
                  <View style={styles.nameGrid}>
                    <View style={[styles.field, styles.nameGridItem]}>
                      <Text style={styles.label}>First Name</Text>
                      <TextInput
                        style={styles.input}
