      setError(err?.message || 'Network error. Please try again.');
    } finally {
      setSimulating(false);
    }
  };

  return (
    <SafeAreaView style={styles.gateScreen}>
    <ScrollView contentContainerStyle={styles.gateContent}>
      <Image
        source={require('@/assets/images/16:9.png')}
        style={styles.gateLogo}
        resizeMode="contain"
